/* Code block: dark panel (always dark, like toasts), thin rule, square corners. The copy button is an icon button
   inside the panel: in the header row when there is a title, otherwise floating in the top corner. */
.code-block { position: relative; background: var(--surface); color: var(--surface-text); border: 1px solid var(--rule); font-size: var(--text-sm); }
.code-head { display: flex; justify-content: space-between; align-items: center; gap: var(--s3); min-height: var(--s7); padding-block: var(--s1); padding-inline: var(--s4) var(--s2); border-bottom: 1px solid var(--rule); }
.code-title { font-size: var(--text-xs); letter-spacing: 0.04em; color: var(--surface-text); opacity: 0.75; overflow-wrap: anywhere; }
.code-copy { display: inline-grid; place-items: center; flex: none; width: var(--s6); height: var(--s6); color: var(--surface-text); opacity: 0.8; border: 1px solid transparent; }
.code-copy:hover { opacity: 1; border-color: var(--rule); background: var(--wash); }
.code-copy[data-copied] { color: var(--code-string); opacity: 1; }
.code-copy:focus-visible { outline: 2px solid var(--accent); outline-offset: 1px; opacity: 1; }
.code-block[data-headless] .code-copy { position: absolute; inset-block-start: var(--s2); inset-inline-end: var(--s2); z-index: 1; }
.code-block[data-headless] pre { padding-inline-end: var(--s8); }
.code-block pre { margin: 0; padding: var(--s4); overflow-x: auto; line-height: 1.6; tab-size: 2; }
.code-block pre:focus-visible { outline: 2px solid var(--accent); outline-offset: -2px; }
.code-block code { font-family: var(--font-body); white-space: pre; display: block; width: max-content; min-width: 100%; }
.code-block pre[data-lines] { counter-reset: line; }
.code-block pre[data-lines] .code-line::before { counter-increment: line; content: counter(line); display: inline-block; width: 2.5ch; margin-inline-end: var(--s4); text-align: end; color: var(--code-comment); opacity: 0.7; user-select: none; }
.tok-keyword { color: var(--code-keyword); }
.tok-string { color: var(--code-string); }
.tok-number { color: var(--code-number); }
.tok-comment { color: var(--code-comment); font-style: italic; }
.tok-tag { color: var(--code-tag); }
.tok-attr { color: var(--code-attr); }
.tok-fn { color: var(--code-fn); }

/* ─── Buttons: solid (one per view), line (the rest), danger, ghost ─── */
.btn { min-height: var(--control-md); display: inline-flex; align-items: center; justify-content: center; gap: var(--s3); padding: 14px 24px; font-size: var(--text-sm); font-weight: 500; white-space: nowrap; border-radius: var(--radius); transition: transform var(--base), background var(--fast), color var(--fast); }
.btn:active:not(:disabled) { transform: scale(0.98); }
.btn:disabled { opacity: 0.55; cursor: not-allowed; }
.btn-solid { background: var(--foreground); color: var(--background); }
.btn-solid:hover:not(:disabled) { background: var(--ink-2); }
.btn-line { box-shadow: inset 0 0 0 1px var(--foreground); }
.btn-line:hover:not(:disabled) { background: var(--foreground); color: var(--background); }
.btn-danger { box-shadow: inset 0 0 0 1px var(--danger); color: var(--danger); }
.btn-danger:hover:not(:disabled) { background: var(--danger); color: var(--background); }
.btn-ghost { min-height: 0; padding-inline-start: 0; padding-inline-end: 0; text-decoration: underline; text-underline-offset: 4px; text-decoration-color: var(--muted); }
.btn-ghost:hover:not(:disabled) { text-decoration-color: currentColor; }
.btn-sm { min-height: var(--control-sm); padding: 6px 12px; font-size: var(--text-xs); }
.btn-lg { min-height: var(--control-lg); padding: 14px 32px; font-size: var(--text-base); }
.btn-ghost.btn-sm, .btn-ghost.btn-lg { min-height: 0; }
.btn-block { width: 100%; }

source.content:
'use client';
import {forwardRef, useEffect, useMemo, useRef, useState, type HTMLAttributes} from 'react';
import {cx} from '../../utils/cx';
import {highlight, languageFromName, type Language, type Token} from '../../utils/highlight';

export interface CodeBlockProps extends Omit<HTMLAttributes<HTMLDivElement>, 'children'> {
  /** The text to show and to copy. Rendered as text with coloured spans, never as HTML. */
  code: string;
  /** A file name (`button.tsx`) or label (`bash`) shown in the header. Also names the region and picks the language. */
  title?: string;
  /** Syntax colouring: `tsx`, `ts`, `jsx`, `js`, `css`, `html`, `bash`, `json` or `text`. Default: guessed from `title`, else `text`. */
  language?: Language;
  /** Number each line. Use for longer listings, not one-line commands. */
  lineNumbers?: boolean;
  /** Hide the copy button. */
  hideCopy?: boolean;
}

const CopyIcon = () => <svg aria-hidden="true" viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.25"><rect x="5.5" y="5.5" width="8" height="8" /><path d="M10.5 5.5v-3h-8v8h3" /></svg>;
const CheckIcon = () => <svg aria-hidden="true" viewBox="0 0 16 16" width="16" height="16" fill="none" stroke="currentColor" strokeWidth="1.5"><path d="M3 8.5l3.2 3.2L13 4.8" /></svg>;

/** Split tokens into lines, keeping each token's type. */
function toLines(tokens: Token[]): Token[][] {
  const lines: Token[][] = [[]];
  for (const t of tokens) {
    const parts = t.text.split('\n');
    parts.forEach((part, i) => {
      if (i > 0) lines.push([]);
      if (part) lines[lines.length - 1]!.push({type: t.type, text: part});
    });
  }
  return lines;
}

/**
 * Syntax-coloured code with an icon copy button inside the panel. With a `title` the button sits in a header
 * row; without one it floats in the top corner. The copy button announces "Copied" politely.
 * @example <CodeBlock title="app.tsx" code={source} lineNumbers />
 */
export const CodeBlock = forwardRef<HTMLDivElement, CodeBlockProps>(function CodeBlock({code, title, language, lineNumbers, hideCopy, className, ...rest}, ref) {
  const [copied, setCopied] = useState(false);
  const timer = useRef<ReturnType<typeof setTimeout>>(undefined);
  useEffect(() => () => clearTimeout(timer.current), []);
  const lang = language ?? languageFromName(title);
  const lines = useMemo(() => toLines(highlight(code.replace(/\n$/, ''), lang)), [code, lang]);
  const copy = async () => {
    try { await navigator.clipboard.writeText(code); setCopied(true); clearTimeout(timer.current); timer.current = setTimeout(() => setCopied(false), 1800); } catch { setCopied(false); }
  };
  const button = !hideCopy && (
    <button type="button" className="code-copy" onClick={copy} aria-label={copied ? 'Copied' : 'Copy code'} data-copied={copied || undefined}>
      {copied ? <CheckIcon /> : <CopyIcon />}
    </button>
  );
  return (
    <div ref={ref} role="group" aria-label={title ?? 'Code'} className={cx('code-block', className)} data-headless={!title || undefined} data-language={lang} {...rest}>
      {title && (
        <div className="code-head">
          <span className="code-title">{title}</span>
          {button}
        </div>
      )}
      {!title && button}
      <pre tabIndex={0} data-lines={lineNumbers || undefined}>
        <code>
          {lines.map((line, i) => (
            <span key={i} className="code-line">
              {line.map((t, j) => (t.type === 'plain' ? t.text : <span key={j} className={`tok-${t.type}`}>{t.text}</span>))}
              {'\n'}
            </span>
          ))}
        </code>
      </pre>
      <span className="sr-only" role="status">{copied ? 'Copied to clipboard' : ''}</span>
    </div>
  );
});
